import numpy as np

def classify(M):
    rows, cols = M.shape
    types = []
    if rows == cols:
        types.append('square')
    else:
        types.append('rectangular')
    if np.all(M == 0):
        types.append('zero')
    if np.allclose(M, np.eye(rows)):
        types.append('identity')
    if np.allclose(M, np.diag(np.diag(M))):
        types.append('diagonal')
    if rows == cols and np.allclose(M, M.T):
        types.append('symmetrical')
    if rows == cols and np.allclose(np.triu(M), M):
        types.append('upper triangular')
    if rows == cols and np.allclose(np.tril(M), M):
        types.append('lower triangular')
    return types

# Example usage
A = np.array([[1,0,0],[0,1,0],[0,0,1]])
print(classify(A))  # ['square', 'identity', 'diagonal', 'symmetrical', 'upper triangular', 'lower triangular']

# Manual determinant for triangular matrix
import numpy as np

def tri_det(M):
    n, m = M.shape
    assert n == m, 'Matrix must be square'
    # Verify triangular (upper or lower)
    if np.allclose(np.triu(M), M) or np.allclose(np.tril(M), M):
        return np.prod(np.diag(M))
    else:
        raise ValueError('Matrix is not triangular')

