def is_subspace_3d(vecs):
    import numpy as np
    zero = np.zeros(3, dtype=int)
    if not any(np.array_equal(v, zero) for v in vecs):
        return False
    for i in range(len(vecs)):
        for j in range(len(vecs)):
            if not any(np.array_equal(vecs[i]+vecs[j], v) for v in vecs):
                return False
    for v in vecs:
        for c in [-1,0,2]:
            if not any(np.array_equal(c*v, u) for u in vecs):
                return False
    return True

# Example usage
vectors = [np.array([0,0,0]), np.array([1,2,3]), np.array([-2,-4,-6])]
print(is_subspace_3d(vectors))  # True

