def check_and_invert(matrix):
    if matrix.shape[0] != matrix.shape[1]:
        return "Not square"
    if np.isclose(np.linalg.det(matrix), 0):
        return "Singular"
    return np.linalg.inv(matrix)

import numpy as np
def verify_inverse(A, v):
    A_inv = np.linalg.inv(A)
    w = A @ v
    v_recovered = A_inv @ w
    return np.allclose(v, v_recovered)

import numpy as np
def get_transformation_matrix(T_func, dim):
    basis = np.eye(dim)
    cols = [T_func(basis[:, i]) for i in range(dim)]
    return np.column_stack(cols)

def gram_schmidt_scratch(vectors):
    basis = []
    for v in vectors:
        w = v - sum(np.dot(v, b) * b / np.dot(b, b) for b in basis)
        if np.linalg.norm(w) > 1e-10:
            basis.append(w)
    return [b / np.linalg.norm(b) for b in basis]

import sympy as sp
def evaluate_limit(expr, var, point):
